/* Team Civilians service worker — generated by scripts/build-sw.mjs. Do not edit out/sw.js directly. */
const VERSION = "__VERSION__";
const ROUTES = __ROUTES__;
const ASSETS = __ASSETS__;
const CACHE = `tc-${VERSION}`;

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches
      .open(CACHE)
      .then((c) => c.addAll([...ROUTES, ...ASSETS]))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith("tc-") && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

const routeFor = (path) => {
  const p = path.replace(/\/$/, "").replace(/\.html$/, "") || "/";
  return ROUTES.includes(p) ? p : null;
};

/** Network first (fresh deploys win), falling back to the cache after 3s or when offline. */
async function networkFirst(request, cacheKey) {
  const cache = await caches.open(CACHE);
  try {
    const res = await Promise.race([
      fetch(request),
      new Promise((_, reject) => setTimeout(() => reject(new Error("timeout")), 3000)),
    ]);
    if (res.ok && cacheKey) cache.put(cacheKey, res.clone());
    return res;
  } catch {
    return (await cache.match(cacheKey ?? request, { ignoreSearch: true })) ?? (await cache.match("/")) ?? Response.error();
  }
}

async function cacheFirst(request, ignoreSearch = false) {
  const hit = await caches.match(request, { ignoreSearch });
  if (hit) return hit;
  const res = await fetch(request);
  if (res.ok) (await caches.open(CACHE)).put(request, res.clone());
  return res;
}

async function staleWhileRevalidate(request) {
  const cache = await caches.open(CACHE);
  const hit = await cache.match(request);
  const fresh = fetch(request)
    .then((res) => (res.ok && cache.put(request, res.clone()), res))
    .catch(() => hit);
  return hit ?? fresh;
}

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET") return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  if (request.mode === "navigate") {
    event.respondWith(networkFirst(request, routeFor(url.pathname) ?? undefined));
  } else if (url.pathname === "/data/questions.json") {
    event.respondWith(staleWhileRevalidate(request));
  } else if (url.pathname.startsWith("/_next/static/") || url.pathname.startsWith("/icons/")) {
    event.respondWith(cacheFirst(request));
  } else if (url.pathname.endsWith(".txt")) {
    // RSC payloads for client-side navigation; the ?_rsc cache-buster varies per request.
    event.respondWith(cacheFirst(request, true).catch(() => Response.error()));
  }
});
